            r'\$\{e\.alert\?\.signature',
            r'\$\{e\.alert\?\.rule',
            r'\$\{e\.alert\?\.category',
            r'\$\{e\.dns\?\.rrname',
            r'\$\{e\.dns\?\.rrtype',
            r'\$\{e\.http\?\.http_method',
            r'\$\{e\.http\?\.url',
            r'\$\{e\.http\?\.hostname',
            r'\$\{e\.http\?\.http_user_agent',
            r'\$\{e\.http\?\.http_content_type',
            r'\$\{e\.tls\?\.sni',
